mapper.select:
select bo.id, bo.status, bo.operator, bo.proposer, bo.priority, bo.env, bo.reason, bo.source, bo.belong,
bo.return_count,
bo.create_date, bo.modify_date,
bo.name bugName,
p.name projectName,
pl.name productLineName,
bd.name bizDomainName
from bug_offline bo
join project p on bo.project_id = p.id
join product_line pl on pl.id = bo.product_line_id
join biz_domain bd on pl.biz_domain_id = bd.id


        and bo.name like concat('%',#{name},'%')


        and bo.status in

            #{item}



        and bo.operator_id in

            #{item}



        and bo.proposer_id in

            #{item}



        and bo.project_id in

            #{item}



        and bo.product_line_id in

            #{item}



        and bo.priority in

            #{item}



        and bo.env in

            #{item}



        and bo.reason in

            #{item}



        and bo.source in

            #{item}



        and bo.belong in

            #{item}



        and bo.create_date >= #{createDateLeft} and bo.create_date <= #{createDateRight}


        and bo.modify_date >= #{modifyDateLeft} and bo.modify_date <= #{modifyDateRight}


        and bo.return_count = #{returnCount}
        and bo.return_count > #{returnCount}
        and bo.return_count >= #{returnCount}
        and bo.return_count < #{returnCount}
        and bo.return_count <= #{returnCount}


        and bo.id IN (
        select p.main_id
        from person p
        where p.user_id = #{copier} p.type = 50
        )
